// دریافت زنده دلار/طلا/سکه از tgju و ساخت متن هشدار (بدون توصیه خرید/فروش)
const keys = [['price_dollar_rl','دلار',0.8],['geram18','گرم طلا ۱۸',0.8],['sekeb','سکه امامی',1.0]];
const lines = [];
for (const [k, fa, th] of keys) {
  const d = await this.helpers.httpRequest({ url: `https://api.tgju.org/v1/market/indicator/summary-table-data/${k}`, json: true });
  const row = d.data[0];
  const pct = parseFloat(String(row[5]).replace(/<[^>]+>/g,'').replace('%',''));
  const price = parseFloat(String(row[0]).replace(/,/g,'')) / 10;
  lines.push(`${fa}: ${price.toLocaleString('fa-IR')} ت  (${pct>=0?'▲':'▼'}${pct.toFixed(2)}٪)`);
  if (Math.abs(pct) >= th) lines.push('');
}
const strong = lines.some(l => l.includes('▲0.') || l.includes('▼0.'));
return [{ json: { text: '📡 رادار دارایی‌ها\n' + lines.join('\n') } }];
